import java.util.ArrayList;
import java.util.List;

public class StaffDirectoryTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    public static void main(String[] args) {
        StaffMember ada = new StaffDirectory.Nurse("Ada", "C3");
        StaffMember bo = new StaffDirectory.Driver("Bo", 7);

        check("the nurse keeps the inherited name", "Ada", ada.getName());
        check("nurse describe uses the badge helper", "NURSE/ada ward C3", ada.describe());
        check("driver describe uses the badge helper", "DRIVER/bo van 7", bo.describe());

        List<StaffMember> staff = new ArrayList<>();
        staff.add(ada);
        staff.add(bo);
        staff.add(new StaffDirectory.Driver("Cy", 2));

        check("roster joins the polymorphic descriptions",
                "NURSE/ada ward C3, DRIVER/bo van 7, DRIVER/cy van 2", StaffDirectory.roster(staff));
        check("roster of an empty list", "", StaffDirectory.roster(new ArrayList<StaffMember>()));
        check("countDrivers", 2, StaffDirectory.countDrivers(staff));
        check("countDrivers on an empty list", 0, StaffDirectory.countDrivers(new ArrayList<StaffMember>()));

        StaffMember onlyNurse = new StaffDirectory.Nurse("Dee", "A1");
        check("a second nurse formats independently", "NURSE/dee ward A1", onlyNurse.describe());

        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

