import java.util.List;

/**
 * TASK: Complete the two subclasses and the two static methods in
 * StaffDirectory. The abstract class StaffMember above it is provided
 * and already works -- do not change it.
 *
 * StaffMember keeps the name private but hands subclasses a PROTECTED
 * helper, badge(role), that builds "NURSE/ada" from the role and the name.
 * Both subclasses must reuse that helper instead of formatting by hand.
 *
 * Rules:
 *   - Nurse.describe()  -> badge("nurse") + " ward " + ward   ("NURSE/ada ward C3")
 *   - Driver.describe() -> badge("driver") + " van " + vanNumber ("DRIVER/bo van 7")
 *   - roster(list) joins every member's describe() with ", " ("" when empty)
 *   - countDrivers(list) counts how many members are Drivers
 *
 * Example: roster(List.of(new StaffDirectory.Nurse("Ada", "C3")))
 *   returns "NURSE/ada ward C3".
 */
abstract class StaffMember {

    private final String name;

    protected StaffMember(String name) {
        this.name = name;
    }

    public String getName() {
        return name;
    }

    /** Provided helper for subclasses: badge("nurse") on Ada gives "NURSE/ada". */
    protected String badge(String role) {
        return role.toUpperCase() + "/" + name.toLowerCase();
    }

    public abstract String describe();
}

public class StaffDirectory {

    public static class Nurse extends StaffMember {

        private final String ward;

        public Nurse(String name, String ward) {
            super(name);
            this.ward = ward;
        }

        @Override
        public String describe() {
            return badge("nurse") + " ward " + ward;
        }
    }

    public static class Driver extends StaffMember {

        private final int vanNumber;

        public Driver(String name, int vanNumber) {
            super(name);
            this.vanNumber = vanNumber;
        }

        @Override
        public String describe() {
            return badge("driver") + " van " + vanNumber;
        }
    }

    public static String roster(List<StaffMember> staff) {
        StringBuilder text = new StringBuilder();
        for (StaffMember member : staff) {
            if (text.length() > 0) {
                text.append(", ");
            }
            text.append(member.describe());
        }
        return text.toString();
    }

    public static int countDrivers(List<StaffMember> staff) {
        int drivers = 0;
        for (StaffMember member : staff) {
            if (member instanceof Driver) {
                drivers++;
            }
        }
        return drivers;
    }
}
